// Cm TSバックエンドのフロントエンドFFIテスト用の最小React風fixture（本物のreactではなくcreateElement/renderToStringの互換実装）
function createElement(type, props, ...children) {
    return { type: type, props: props || {}, children: children.flat() };
}
function renderToString(node) {
    if (node === null || node === undefined) return "";
    if (typeof node === "string" || typeof node === "number") return String(node);
    if (typeof node.type === "function") return renderToString(node.type(node.props));
    const attrs = Object.keys(node.props || {})
        .filter((k) => node.props[k] !== undefined && node.props[k] !== null)
        .map((k) => " " + k + '="' + node.props[k] + '"')
        .join("");
    const inner = (node.children || []).map(renderToString).join("");
    return "<" + node.type + attrs + ">" + inner + "</" + node.type + ">";
}
function renderList(items) {
    return "<ul>" + items.map((it) => "<li>" + it.label + "</li>").join("") + "</ul>";
}
function maybeValue(flag) {
    return flag ? "present" : undefined;
}
module.exports = { createElement, renderToString, renderList, maybeValue };
